const Z = 'Asia/Dubai';
const inp = $('Booking Request').first().json;
const action = String(inp.action || '');
let from;
let to;
if (action === 'find_slots') {
  const d = DateTime.fromISO(String(inp.date || ''), { zone: Z });
  const base = d.isValid ? d : DateTime.now().setZone(Z);
  from = base.startOf('day');
  const n = Math.min(Math.max(Number(inp.days) || 1, 1), 7);
  to = from.plus({ days: n });
} else if (action === 'book' || action === 'reschedule') {
  const s = DateTime.fromFormat(String(inp.start || ''), 'yyyy-MM-dd HH:mm', { zone: Z });
  const base = s.isValid ? s : DateTime.now().setZone(Z);
  from = base.startOf('day');
  to = from.plus({ days: 1 });
} else {
  from = DateTime.now().setZone(Z).startOf('day');
  to = from.plus({ days: 1 });
}
return [{ json: { timeMin: from.toISO(), timeMax: to.toISO() } }];

// ===== Clinic rules =====
// With the clinic_setup switch ON these come from the Clinic Setup, Prices and Dentists tabs of the Sheet.
// The values below are the fallback (switch OFF, or the tabs are empty).
const Z = 'Asia/Dubai';
let DENTISTS = {
  'Dr. Sara Haddad': ['consult', 'check', 'clean', 'whiten', 'fill', 'root', 'general', 'cosmetic', 'emergency', 'pain', 'تنظيف', 'تبييض', 'حشو', 'كشف', 'فحص', 'عصب', 'طوارئ'],
  'Dr. Omar Nasser': ['implant', 'extract', 'surgery', 'wisdom', 'root', 'emergency', 'pain', 'consult', 'check', 'زراع', 'خلع', 'جراح', 'عصب', 'طوارئ'],
  'Dr. Lina Farouk': ['align', 'ortho', 'brace', 'child', 'kid', 'consult', 'check', 'تقويم', 'أطفال', 'طفل']
};
let CLOSED_DATES = ['2026-12-02', '2026-12-03', '2027-01-01'];
let MIN_NOTICE_MIN = 60;
let MAX_DAYS_AHEAD = 60;
let LATE_CANCEL_H = 24;
let SLOT = 30;
// Opening hours by weekday (1 = Monday ... 7 = Sunday): [openHour, openMin, closeHour, closeMin], or null = closed.
let HOURS = { 1: [9, 0, 21, 0], 2: [9, 0, 21, 0], 3: [9, 0, 21, 0], 4: [9, 0, 21, 0], 5: [14, 0, 21, 0], 6: [9, 0, 21, 0], 7: [9, 0, 21, 0] };
let DURATIONS = [{ words: ['whiten', 'تبييض'], minutes: 90 }];
let CLINIC_PLACE = 'BrightSmile Dental, Jumeirah';
let LOCATION = 'BrightSmile Dental, Jumeirah, Dubai (demo)';
// =====================================

// Switches: family_bookings and clinic_setup (Noor Settings). Missing or unreadable = OFF.
const SW = {};
try { $('Get Family Switch').all().forEach(function (i) { const r = i.json || {}; if (r.feature) SW[String(r.feature).trim()] = String(r.enabled).trim().toUpperCase() === 'TRUE'; }); } catch (e) { /* off */ }
const familyOn = !!SW.family_bookings;

if (SW.clinic_setup) {
  try {
    const rows = $('Get Setup').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.tab; })
      .sort(function (a, b) { return Number(a.sort || 0) - Number(b.sort || 0); });
    const c = {};
    rows.filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { c[r.name] = String(r.value || '').trim(); });
    const words = function (v) { return String(v || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(Boolean); };
    const dent = {};
    rows.filter(function (r) { return r.tab === 'dentist' && r.name; }).forEach(function (r) { dent[String(r.name).trim()] = words(r.words); });
    if (Object.keys(dent).length) DENTISTS = dent;
    const DAYNUM = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 7 };
    const h = {};
    let anyHours = false;
    Object.keys(DAYNUM).forEach(function (d) {
      const v = String(c['hours_' + d] || '').trim();
      const m = v.match(/^(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})$/);
      if (m) { h[DAYNUM[d]] = [Number(m[1]), Number(m[2]), Number(m[3]), Number(m[4])]; anyHours = true; }
      else if (/closed/i.test(v)) { h[DAYNUM[d]] = null; anyHours = true; }
      else h[DAYNUM[d]] = HOURS[DAYNUM[d]];
    });
    if (anyHours) HOURS = h;
    if (c.closed_dates !== undefined) CLOSED_DATES = String(c.closed_dates).split(/[,;\s]+/).filter(function (x) { return /^\d{4}-\d{2}-\d{2}$/.test(x); });
    if (Number(c.min_notice_minutes) >= 0 && c.min_notice_minutes !== undefined && c.min_notice_minutes !== '') MIN_NOTICE_MIN = Number(c.min_notice_minutes);
    if (Number(c.max_days_ahead) > 0) MAX_DAYS_AHEAD = Number(c.max_days_ahead);
    if (Number(c.late_cancel_hours) >= 0 && c.late_cancel_hours) LATE_CANCEL_H = Number(c.late_cancel_hours);
    if (Number(c.slot_minutes) >= 10) SLOT = Number(c.slot_minutes);
    const durs = rows.filter(function (r) { return r.tab === 'price' && Number(r.minutes) > 0; }).map(function (r) { return { words: words(r.words), minutes: Number(r.minutes) }; });
    if (durs.length) DURATIONS = durs;
    if (c.clinic_name) {
      CLINIC_PLACE = c.clinic_name + (c.address ? ', ' + c.address : '');
      LOCATION = CLINIC_PLACE;
    }
  } catch (e) { /* keep fallback values */ }
}

const ALL = Object.keys(DENTISTS);
const inp = $('Booking Request').first().json;
const row = $('Find Patient').first().json || {};
const range = $('Prepare Range').first().json;
const events = $input.all().map(i => i.json).filter(e => e && e.start && (e.start.dateTime || e.start.date) && e.status !== 'cancelled');
const now = DateTime.now().setZone(Z);
const nowStr = now.toFormat('yyyy-MM-dd HH:mm');

function firstName(n) { return String(n || '').toLowerCase().replace(/[^a-z؀-ۿ ]/g, ' ').trim().split(/\s+/)[0] || ''; }
function duration(service) {
  const s = String(service || '').toLowerCase();
  const d = DURATIONS.find(function (x) { return x.words.some(function (w) { return s.includes(w); }); });
  return d ? d.minutes : SLOT;
}
function eligible(service, wanted) {
  if (wanted) {
    const last = String(wanted).toLowerCase().replace('dr.', '').trim().split(' ').pop();
    const w = ALL.find(d => d.toLowerCase().includes(last));
    if (w) return [w];
  }
  const s = String(service || '').toLowerCase();
  const list = ALL.filter(d => DENTISTS[d].some(k => s.includes(k)));
  return list.length ? list : ALL;
}
function hours(day) {
  if (CLOSED_DATES.includes(day.toFormat('yyyy-MM-dd'))) return null;
  const h = HOURS[day.weekday];
  if (!h) return null;
  return { open: day.set({ hour: h[0], minute: h[1], second: 0, millisecond: 0 }), close: day.set({ hour: h[2], minute: h[3], second: 0, millisecond: 0 }) };
}
function dentistOf(ev) {
  const t = String(ev.description || '') + ' ' + String(ev.summary || '');
  return ALL.find(x => t.includes(x)) || null; // events without a dentist block everyone
}
function busy(dentist, s, e, ignoreId) {
  return events.some(ev => {
    if (ignoreId && ev.id === ignoreId) return false;
    const es = DateTime.fromISO(ev.start.dateTime || ev.start.date, { zone: Z });
    const ee = DateTime.fromISO((ev.end && (ev.end.dateTime || ev.end.date)) || ev.start.dateTime, { zone: Z });
    const d = dentistOf(ev);
    if (d && d !== dentist) return false;
    return s < ee && es < e;
  });
}
function invalid(s, dur) {
  const h = hours(s.startOf('day'));
  if (!h) return 'The clinic is closed on that day.';
  if (s < now.plus({ minutes: MIN_NOTICE_MIN })) return 'That time is in the past or too soon (we need at least ' + MIN_NOTICE_MIN + ' minutes notice).';
  if (s > now.plus({ days: MAX_DAYS_AHEAD })) return 'We only book up to ' + MAX_DAYS_AHEAD + ' days ahead.';
  if (s < h.open || s.plus({ minutes: dur }) > h.close) return 'That time is outside opening hours.';
  if (s.diff(h.open, 'minutes').minutes % SLOT !== 0) return 'Appointments start every ' + SLOT + ' minutes from opening time.';
  return null;
}
function fmt(s) { return s.toFormat('cccc d LLLL, h:mm a'); }
function reply(ok, message) { return [{ json: { op: 'reply', ok, message } }]; }

const action = String(inp.action || '');
const service = String(inp.service || row.service || '');

let existing = null;
if (row.calendar_event_id && row.appointment_start && /booked|confirmed/i.test(String(row.status || ''))) {
  const es = DateTime.fromFormat(String(row.appointment_start), 'yyyy-MM-dd HH:mm', { zone: Z });
  if (es.isValid && es > now) existing = { start: es, id: String(row.calendar_event_id), dentist: String(row.dentist || ''), service: String(row.service || '') };
}

if (action === 'find_slots') {
  const dur = duration(service);
  const base = DateTime.fromISO(range.timeMin, { zone: Z });
  const days = Math.round(DateTime.fromISO(range.timeMax, { zone: Z }).diff(base, 'days').days);
  const docs = eligible(service, inp.dentist);
  const lines = [];
  const web = String(inp.source || '') === 'web';
  const all = [];
  for (let i = 0; i < days; i++) {
    const day = base.plus({ days: i });
    const h = hours(day);
    if (!h) { lines.push(day.toFormat('cccc d LLLL') + ': closed'); continue; }
    const slots = [];
    for (let s = h.open; s.plus({ minutes: dur }) <= h.close; s = s.plus({ minutes: SLOT })) {
      if (invalid(s, dur)) continue;
      const d = docs.find(doc => !busy(doc, s, s.plus({ minutes: dur })));
      if (d) { slots.push(s.toFormat('HH:mm') + ' (' + d + ')'); all.push({ date: day.toFormat('yyyy-MM-dd'), time: s.toFormat('HH:mm'), dentist: d }); }
    }
    lines.push(day.toFormat('cccc d LLLL (yyyy-MM-dd)') + ': ' + (slots.length ? slots.slice(0, 12).join(', ') + (slots.length > 12 ? ' (+' + (slots.length - 12) + ' more later in the day)' : '') : 'fully booked'));
  }
  let msg = 'Free ' + dur + '-minute slots for "' + (service || 'consultation') + '" (Dubai time). Offer the patient up to 3 that fit what they asked:\n' + lines.join('\n');
  if (existing) msg += '\nNote: this patient already has a booking on ' + fmt(existing.start) + ' with ' + existing.dentist + '.';
  const res = reply(true, msg);
  if (web) res[0].json.slots = all; // online booking page needs every free slot
  return res;
}

if (action === 'my_booking') {
  return reply(true, existing ? 'Upcoming booking: ' + existing.service + ' on ' + fmt(existing.start) + ' with ' + existing.dentist + '.' : 'This patient has no upcoming booking.');
}

if (action === 'book' || action === 'reschedule') {
  const s = DateTime.fromFormat(String(inp.start || ''), 'yyyy-MM-dd HH:mm', { zone: Z });
  if (!s.isValid) return reply(false, 'Invalid start time. Use YYYY-MM-DD HH:mm in Dubai time.');
  // Family booking: same phone, a different person (different first name) than the one already booked.
  const wantName = String(inp.name || '').trim();
  const family = action === 'book' && !!existing && familyOn && !!firstName(wantName) && !!firstName(row.name) && firstName(wantName) !== firstName(row.name);
  if (action === 'book' && existing && !family) return reply(false, 'This patient already has a booking on ' + fmt(existing.start) + '. Ask whether they want to move it (reschedule_appointment) instead.');
  if (action === 'reschedule' && !existing) return reply(false, 'This patient has no upcoming booking to move. Use book_appointment instead.');
  const svc = action === 'reschedule' ? (existing.service || service) : service;
  if (!svc) return reply(false, 'The service is missing. Ask the patient which service they need.');
  const dur = duration(svc);
  const why = invalid(s, dur);
  if (why) return reply(false, why + ' Use find_free_slots and offer valid times.');
  const ignore = action === 'reschedule' ? existing.id : null;
  const docs = eligible(svc, inp.dentist || (action === 'reschedule' ? existing.dentist : ''));
  const doc = docs.find(d => !busy(d, s, s.plus({ minutes: dur }), ignore));
  if (!doc) return reply(false, 'That slot is no longer free. Use find_free_slots and offer other times.');
  const name = String(inp.name || row.name || '').trim();
  if (action === 'book' && !name) return reply(false, "The patient's full name is missing. Ask for it first.");
  if (family) {
    return [{ json: {
      op: 'create_family', ok: true, location: LOCATION,
      start: s.toISO(), end: s.plus({ minutes: dur }).toISO(),
      summary: svc + ' – ' + name,
      description: 'Booked by Noor on WhatsApp for a family member. Contact phone: +' + inp.phone + '. Dentist: ' + doc + '.',
      message: 'Booked for ' + name + ': ' + svc + ' on ' + fmt(s) + ' with ' + doc + ' at ' + CLINIC_PLACE + '. This is a second booking on the same phone, so it is in the calendar but not in the patient record. Confirm this to the patient. If they later ask to move or cancel it, do not use the cancel or reschedule tools (they would change the first booking): ask the team through a request.'
    } }];
  }
  return [{ json: {
    op: action === 'book' ? 'create' : 'update', ok: true, location: LOCATION,
    eventId: ignore || '', start: s.toISO(), end: s.plus({ minutes: dur }).toISO(),
    summary: svc + ' – ' + (name || 'Patient'),
    description: 'Booked by Noor on ' + (String(inp.source || '') === 'web' ? 'the online booking page' : 'WhatsApp') + '. Patient phone: +' + inp.phone + '. Dentist: ' + doc + '.',
    sheet: {
      phone: String(inp.phone), name, language: String(inp.language || row.language || ''),
      new_or_returning: String(inp.new_or_returning || row.new_or_returning || ''), service: svc,
      insurance: String(inp.insurance || row.insurance || ''), status: 'booked',
      appointment_start: s.toFormat('yyyy-MM-dd HH:mm'), dentist: doc, last_message_at: nowStr
    },
    message: (action === 'book' ? 'Booked: ' : 'Moved to: ') + svc + ' on ' + fmt(s) + ' with ' + doc + ' at ' + CLINIC_PLACE + '. Confirm this to the patient.'
  } }];
}

if (action === 'cancel') {
  if (!existing) return reply(false, 'This patient has no upcoming booking to cancel.');
  const late = existing.start.diff(now, 'hours').hours < LATE_CANCEL_H;
  return [{ json: {
    op: 'delete', ok: true, eventId: existing.id,
    sheet: { phone: String(inp.phone), status: 'cancelled', appointment_start: '', dentist: '', calendar_event_id: '', last_message_at: nowStr },
    message: 'Cancelled the ' + existing.service + ' appointment on ' + fmt(existing.start) + '.' + (late ? ' It was less than ' + LATE_CANCEL_H + ' hours before the visit, so mention the ' + LATE_CANCEL_H + '-hour notice policy kindly.' : '') + ' Tell the patient and offer a new time.'
  } }];
}

return reply(false, 'Unknown action: ' + action);

// Test phones (9715000009...) are used by the Test Suite: never write to the calendar or the Sheet for them.
const r = $input.first().json;
const ph = String($('Booking Request').first().json.phone || '').replace(/\D/g, '');
if (/^000000000000/.test(ph) && ['create', 'update', 'delete', 'create_family'].indexOf(r.op) >= 0) {
  return [{ json: { op: 'reply', ok: true, message: r.message, test_dry_run: true } }];
}
return [{ json: r }];

// Family booking row for the Family Bookings tab, so reminders and review requests work for family members too.
const be = $('Booking Engine').first().json;
const inp = $('Booking Request').first().json;
const ev = $input.first().json || {};
const s = DateTime.fromISO(String(be.start), { zone: 'Asia/Dubai' });
const dm = String(be.description || '').match(/Dentist: (.+?)\.$/);
return [{ json: {
  key: String(ev.id || ''), phone: String(inp.phone || ''), name: String(inp.name || ''), service: String(inp.service || ''),
  appointment_start: s.isValid ? s.toFormat('yyyy-MM-dd HH:mm') : '', dentist: dm ? dm[1] : '', status: 'booked',
  calendar_event_id: String(ev.id || ''), booked_at: DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm'),
  reminder_24h_sent: '', reminder_2h_sent: '', review_requested: ''
} }];
